using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace MuscleBattle
{
    /// <summary>
    /// BGM with crossfade + synced "final round" intensity layer (§34), pooled SFX sources with
    /// random variation / pitch so nothing repeats identically (§36), announcer (§38), ducking.
    /// Clips live in Resources/Audio (generated by tools/generate_audio.py - all original).
    ///
    /// WebGL/iPad note: browsers block audio until the first user gesture. The title screen's
    /// "PRESS START / TAP" doubles as that unlock, so the first sound is never lost.
    /// </summary>
    public sealed class AudioManager : MonoBehaviour
    {
        public static AudioManager Instance { get; private set; }

        const int SfxPoolSize = 16;
        readonly List<AudioSource> _sfx = new List<AudioSource>();
        int _sfxNext;
        AudioSource _bgmA, _bgmB, _layer, _tension, _voice;
        bool _tensionOn;
        bool _aIsActive = true;
        readonly Dictionary<string, AudioClip> _clips = new Dictionary<string, AudioClip>();
        readonly Dictionary<string, int> _variantCounts = new Dictionary<string, int>();
        readonly Dictionary<string, int> _lastVariant = new Dictionary<string, int>();
        float _duck = 1f, _duckTarget = 1f, _duckTimer;
        bool _layerOn;
        string _currentBgm;

        void Awake()
        {
            Instance = this;
            for (int i = 0; i < SfxPoolSize; i++) _sfx.Add(NewSource("sfx" + i));
            _bgmA = NewSource("bgmA");
            _bgmB = NewSource("bgmB");
            _layer = NewSource("bgmLayer");
            _tension = NewSource("bgmTension");
            _tension.loop = true;
            _voice = NewSource("announcer");
            _layer.loop = true;
            _voice.priority = 0;

            // count variations: punch_0..punch_3 etc
            foreach (var key in new[] { "punch", "kick", "heavy", "block", "counter", "whoosh", "land", "ko_boom", "grab", "launch", "special", "meter_full", "knockdown", "link_charge", "link_success", "link_fail" })
            {
                int n = 0;
                while (Load("SFX/" + key + "_" + n) != null) n++;
                _variantCounts[key] = n;
            }
        }

        AudioSource NewSource(string n)
        {
            var go = new GameObject(n);
            go.transform.SetParent(transform, false);
            var s = go.AddComponent<AudioSource>();
            s.playOnAwake = false;
            s.spatialBlend = 0f; // 2D: fighting games mix everything front and centre
            return s;
        }

        AudioClip Load(string path)
        {
            if (_clips.TryGetValue(path, out var c)) return c;
            c = Resources.Load<AudioClip>("Audio/" + path);
            _clips[path] = c;
            return c;
        }

        // ------------------------------------------------------------------
        // SFX
        // ------------------------------------------------------------------
        public void PlaySfx(string name, float volume = 1f, float pitch = 1f)
        {
            var clip = Load("SFX/" + name) ?? Load("SFX/" + name + "_0");
            Play(clip, volume, pitch);
        }

        /// <summary>Random variation without immediate repeats, slight pitch randomisation.</summary>
        public void PlayVariant(string key, Vector3 pos, float volume = 1f)
        {
            if (!_variantCounts.TryGetValue(key, out int n) || n == 0) { PlaySfx(key, volume); return; }
            int idx = Random.Range(0, n);
            if (n > 1 && _lastVariant.TryGetValue(key, out int last) && last == idx) idx = (idx + 1) % n;
            _lastVariant[key] = idx;
            Play(Load("SFX/" + key + "_" + idx), volume, Random.Range(0.94f, 1.06f));
        }

        public void PlayImpact(SfxKind kind, ImpactTier tier, Vector3 pos)
        {
            switch (kind)
            {
                case SfxKind.Kick: PlayVariant("kick", pos, 0.9f); break;
                case SfxKind.Heavy: PlayVariant("heavy", pos, 1f); break;
                case SfxKind.Grab: PlayVariant("grab", pos, 0.9f); break;
                default: PlayVariant("punch", pos, tier == ImpactTier.Light ? 0.75f : 0.9f); break;
            }
            // layered bass for the big ones (§36 "Ultimate: layered sound")
            if (tier >= ImpactTier.Heavy && kind != SfxKind.Heavy) PlayVariant("heavy", pos, 0.45f);
            if (tier == ImpactTier.Ultimate) PlaySfx("ko_boom", 0.35f, 1.3f);
        }

        void Play(AudioClip clip, float volume, float pitch)
        {
            if (clip == null) return;
            var s = _sfx[_sfxNext];
            _sfxNext = (_sfxNext + 1) % _sfx.Count;
            s.pitch = pitch;
            s.PlayOneShot(clip, volume * GameSettings.SfxVolume);
        }

        public void Announce(string key)
        {
            var clip = Load("Announcer/" + key);
            if (clip == null) return;
            _voice.Stop();
            _voice.clip = clip;
            _voice.volume = GameSettings.VoiceVolume;
            _voice.Play();
            DuckMusic(0.55f, clip.length);
        }

        // ------------------------------------------------------------------
        // BGM
        // ------------------------------------------------------------------
        public void PlayBgm(string name, bool loop, float fade = 0.6f)
        {
            if (_currentBgm == name && Active.isPlaying) return;
            var clip = Load("BGM/" + name);
            if (clip == null) return;
            _currentBgm = name;
            var from = Active;
            _aIsActive = !_aIsActive;
            var to = Active;
            to.clip = clip;
            to.loop = loop;
            to.volume = 0;
            to.Play();
            StopAllCoroutines();
            StartCoroutine(Crossfade(from, to, fade));

            // final round layer is sample-locked to the battle loop
            if (name == "battle")
            {
                _layer.clip = Load("BGM/battle_final_layer");
                _layer.volume = 0;
                if (_layer.clip != null)
                {
                    _layer.timeSamples = 0;
                    _layer.Play();
                }
                _tension.clip = Load("BGM/battle_tension_layer");
                _tension.volume = 0;
                if (_tension.clip != null)
                {
                    _tension.timeSamples = 0;
                    _tension.Play();
                }
            }
            else
            {
                _layer.Stop();
                _tension.Stop();
                _layerOn = _tensionOn = false;
            }
        }

        public void StopBgm(float fade = 0.5f)
        {
            _currentBgm = null;
            StopAllCoroutines();
            StartCoroutine(Crossfade(Active, null, fade));
            _layer.Stop();
            _tension.Stop();
        }

        public void SetFinalRoundLayer(bool on) => _layerOn = on;

        /// <summary>Low-HP tension layer (heartbeat + drone), sample-locked to the battle loop (§21).</summary>
        public void SetTensionLayer(bool on) => _tensionOn = on;

        /// <summary>KO: hard music cut so the impact lands in silence (§21), victory sting follows.</summary>
        public void CutMusic()
        {
            _currentBgm = null;
            StopAllCoroutines();
            _bgmA.Stop();
            _bgmB.Stop();
            _layer.Stop();
            _tension.Stop();
        }

        public void DuckMusic(float level, float seconds)
        {
            _duckTarget = Mathf.Min(_duckTarget, level);
            _duckTimer = Mathf.Max(_duckTimer, seconds);
        }

        AudioSource Active => _aIsActive ? _bgmA : _bgmB;

        IEnumerator Crossfade(AudioSource from, AudioSource to, float seconds)
        {
            float t = 0;
            float fromStart = from != null ? from.volume : 0;
            while (t < seconds)
            {
                t += Time.unscaledDeltaTime;
                float k = Mathf.Clamp01(t / seconds);
                if (from != null && from != to) from.volume = fromStart * (1 - k);
                if (to != null) to.volume = MusicLevel * k;
                yield return null;
            }
            if (from != null && from != to) from.Stop();
        }

        float MusicLevel => GameSettings.MusicVolume * _duck * 0.8f;

        void Update()
        {
            float dt = Time.unscaledDeltaTime;
            if (_duckTimer > 0) _duckTimer -= dt;
            else _duckTarget = 1f;
            _duck = Mathf.MoveTowards(_duck, _duckTarget, dt * (_duckTarget < _duck ? 6f : 1.5f));

            var a = Active;
            if (a.isPlaying && a.volume > 0.001f) a.volume = Mathf.MoveTowards(a.volume, MusicLevel, dt * 2f);
            if (_layer.isPlaying)
            {
                if (a.isPlaying && a.clip != null && _layer.clip != null && Mathf.Abs(_layer.timeSamples - a.timeSamples) > 2048)
                    _layer.timeSamples = Mathf.Min(a.timeSamples, _layer.clip.samples - 1);
                _layer.volume = Mathf.MoveTowards(_layer.volume, _layerOn ? MusicLevel * 0.85f : 0f, dt);
            }
            if (_tension.isPlaying)
            {
                if (a.isPlaying && a.clip != null && _tension.clip != null && Mathf.Abs(_tension.timeSamples - a.timeSamples) > 2048)
                    _tension.timeSamples = Mathf.Min(a.timeSamples, _tension.clip.samples - 1);
                _tension.volume = Mathf.MoveTowards(_tension.volume, _tensionOn ? MusicLevel * 0.9f : 0f, dt * 0.8f);
            }
            // slow motion also slows the music slightly - heavy, cinematic feel
            float pitch = Mathf.Lerp(0.85f, 1f, Mathf.InverseLerp(0.2f, 1f, Time.timeScale));
            a.pitch = pitch;
            _layer.pitch = pitch;
            _tension.pitch = pitch;
        }
    }
}
